const MJ_ARM_XML = "<mujoco model=\"Teaching_2R_with_contact\">\n  <compiler angle=\"radian\"/>\n  <option timestep=\"0.002\" gravity=\"0 0 -9.81\" integrator=\"implicitfast\"/>\n  <default>\n    <joint damping=\"1\" armature=\"0.02\"/>\n    <geom friction=\"0.8 0.01 0.001\"/>\n  <\/default>\n  <worldbody>\n    <geom name=\"floor\" type=\"plane\" size=\"1.5 1.5 .1\" rgba=\".12 .18 .26 1\"/>\n    <geom name=\"base\" type=\"cylinder\" pos=\"0 0 .22\" size=\".07 .22\" rgba=\".45 .55 .68 1\"/>\n    <body name=\"upper_arm\" pos=\"0 0 .48\">\n      <joint name=\"shoulder\" axis=\"0 1 0\" range=\"-2.4 2.4\"/>\n      <geom name=\"upper_link\" type=\"capsule\" fromto=\"0 0 0 .45 0 0\" size=\".035\" mass=\".6\" rgba=\"1 .65 .28 1\"/>\n      <body name=\"forearm\" pos=\".45 0 0\">\n        <joint name=\"elbow\" axis=\"0 1 0\" range=\"-2.4 2.4\"/>\n        <geom name=\"fore_link\" type=\"capsule\" fromto=\"0 0 0 .35 0 0\" size=\".03\" mass=\".4\" rgba=\".3 .8 .68 1\"/>\n        <site name=\"tcp\" pos=\".35 0 0\" size=\".025\" rgba=\"1 .3 .3 1\"/>\n      <\/body>\n    <\/body>\n    <body name=\"falling_ball\" pos=\".35 .28 .7\">\n      <freejoint name=\"ball_free\"/>\n      <geom name=\"ball\" type=\"sphere\" size=\".055\" mass=\".15\" rgba=\".55 .45 1 1\"/>\n    <\/body>\n  <\/worldbody>\n  <actuator>\n    <position name=\"shoulder_servo\" joint=\"shoulder\" kp=\"25\" ctrlrange=\"-2.4 2.4\" forcerange=\"-10 10\"/>\n    <position name=\"elbow_servo\" joint=\"elbow\" kp=\"20\" ctrlrange=\"-2.4 2.4\" forcerange=\"-8 8\"/>\n  <\/actuator>\n<\/mujoco>\n";
const HAND_CODE_PY = "\"\"\"手敲练习：小RGB-D数组 -> 相机点 -> 世界点 -> 像素。\n\n3行4列图像和相机矩阵均为教学数据，不是Scene2真实标定。\n需要Python 3和NumPy。只做数组计算，不读取文件或访问相机、机器人、网络。\n\"\"\"\n\n# SECTION setup\nimport numpy as np\n\n# shape=(3,4,3)：3行、4列，每个像素3个RGB通道。\nrgb = np.array([\n    [[255,0,0], [0,0,0], [0,0,255], [255,255,255]],\n    [[200,80,30], [225,136,61], [40,120,200], [80,160,220]],\n    [[0,0,0], [70,150,170], [0,0,0], [110,180,190]],\n], dtype=np.uint8)\n\n# shape=(3,4)，单位mm。本练习约定原始值0表示深度缺失。\ndepth_mm = np.array([\n    [0, 1000, 2000, 2000],\n    [1500, 1500, 3000, 3000],\n    [0, 2000, 0, 4000],\n], dtype=np.uint16)\n\n# f_x=f_y=2px，c_x=c_y=1px，只用于这张小教学图。\nK = np.array([[2.,0.,1.], [0.,2.,1.], [0.,0.,1.]])\n\n# T_WC把相机C坐标变成世界W坐标。平移单位m。\nT_WC = np.array([\n    [0.,-1.,0., 0.5],\n    [1., 0.,0.,-0.2],\n    [0., 0.,1., 1.0],\n    [0., 0.,0., 1.0],\n])\nu, v = 2, 1  # 列编号、行编号，都从0开始\n\n# SECTION read_depth\ndef read_depth_m(depth_mm, u, v):\n    \"\"\"按[行v,列u]读取，将mm换成m；缺失时返回None。\"\"\"\n    height, width = depth_mm.shape\n    if not (0 <= u < width and 0 <= v < height):\n        raise ValueError(\"pixel is outside the image\")\n    raw = int(depth_mm[v, u])\n    if raw == 0:\n        return None\n    return raw / 1000.0\n\n# SECTION backproject\ndef backproject_pixel(u, v, z_m, K):\n    \"\"\"像素和轴向深度m -> 相机系XYZ，shape=(3,)，单位m。\"\"\"\n    if z_m is None:\n        return None\n    if not np.isfinite(z_m) or z_m <= 0:\n        raise ValueError(\"depth must be a positive finite number\")\n    fx, fy = K[0, 0], K[1, 1]\n    cx, cy = K[0, 2], K[1, 2]\n    x = (u - cx) * z_m / fx\n    y = (v - cy) * z_m / fy\n    return np.array([x, y, z_m], dtype=float)\n\n# SECTION transform\ndef transform_point(p_C, T_WC):\n    \"\"\"相机XYZ -> 世界XYZ；假设输入有效4×4刚体位姿，长度单位m。\"\"\"\n    if p_C is None:\n        return None\n    if p_C.shape != (3,) or T_WC.shape != (4, 4):\n        raise ValueError(\"expected p_C shape (3,) and T_WC shape (4,4)\")\n    R = T_WC[:3, :3]\n    t = T_WC[:3, 3]\n    p_W = R @ p_C + t\n    return p_W\n\n# SECTION project\ndef project_point(p_C, K):\n    \"\"\"相机XYZ -> 浮点像素[u,v]；缺失或后方点返回None。\"\"\"\n    if p_C is None:\n        return None\n    x, y, z = p_C\n    if not np.all(np.isfinite(p_C)) or z <= 0:\n        return None\n    u = K[0, 0] * x / z + K[0, 2]\n    v = K[1, 1] * y / z + K[1, 2]\n    return np.array([u, v])\n\n# SECTION demo\nif __name__ == \"__main__\":\n    print(\"RGB shape:\", rgb.shape, rgb.dtype)\n    print(\"Depth shape:\", depth_mm.shape, depth_mm.dtype)\n    print(\"RGB[v,u]:\", rgb[v, u].tolist())\n    z_m = read_depth_m(depth_mm, u, v)\n    p_C = backproject_pixel(u, v, z_m, K)\n    p_W = transform_point(p_C, T_WC)\n    pixel = project_point(p_C, K)\n    print(\"Z_m:\", z_m)\n    print(\"p_C:\", None if p_C is None else p_C.tolist())\n    print(\"p_W:\", None if p_W is None else np.round(p_W, 6).tolist())\n    print(\"pixel:\", None if pixel is None else pixel.tolist())\n";
